/*
 * render_font.c -- shared bitmap fonts.
 *
 *   font_ascii    ASCII 0x20..0x7E, 8x16 (generated by tools/gen_ascii_font.py);
 *                 one byte per scanline, MSB-left, top-to-bottom.
 *                 No software row-doubling -- every backend indexes g[j] directly.
 *   hz_font       GB2312 16x16 hanzi from GNU Unifont 16.0.01
 *                 (GPLv2+ font-embedding exception / SIL OFL 1.1 --
 *                 see tools/UNIFONT-LICENSE.txt), committed as
 *                 font_hz.inc; regenerated by tools/gen_hz_font.py
 *
 * One asset set, three consumers, all inside the rendering layer:
 *   - be_text.c   loads g[j] directly into VGA plane-2 font slots (16 bytes)
 *   - be_gfx.c    paints text cells into the Mode 13h framebuffer
 *   - be_vbe.c    paints text cells into the 32bpp linear framebuffer
 *
 * No other layer needs glyph data.
 */
#include "render_be.h"
#include "font_ascii.inc"  /* 95 × 16-byte VGA-compatible bitmap */
#include "font_hz.inc"     /* committed Unifont-derived table */

const unsigned char *render_font_glyph(unsigned char ch) {
    /* Fallback '?' -- 16 rows, each original 8-row source duplicated once
     * (matches the layout of font_ascii[] so backends can read g[j] directly). */
    static const unsigned char question[16] = {
        0x00,0x70,0x88,0x08,0x10,0x20,0x00,0x20,
        0x00,0x70,0x88,0x08,0x10,0x20,0x00,0x20
    };
    if (ch < 0x20 || ch > 0x7E) return question;
    return font_ascii[ch - 0x20];
}

/* GB2312 covers U+4E00..U+9FA0.  Table is sorted by codepoint, so a
 * binary search costs ~13 comparisons and no allocation. */
const uint8_t *render_font_hz(uint32_t cp) {
    if (cp < 0x1100 || cp > 0xFFFFu) return 0;
    unsigned lo = 0, hi = HZ_FONT_COUNT;
    while (lo < hi) {
        unsigned m = lo + ((hi - lo) >> 1);
        if ((uint32_t)hz_font[m].cp < cp) lo = m + 1;
        else                             hi = m;
    }
    if (lo < HZ_FONT_COUNT && (uint32_t)hz_font[lo].cp == cp)
        return hz_font[lo].bits;
    return 0;                       /* not covered -> caller draws '?' */
}

unsigned render_font_hz_count(void) { return (unsigned)HZ_FONT_COUNT; }
